# Initially generated by GitHub Copilot.

import re

from pycmn import hebrew_accents as ha
from pycmn import hebrew_letters as hl
from pycmn import hebrew_points as hpo
from pycmn import hebrew_punctuation as hpu
from pycmn import template_names as tmpln
from pycmn import ws_tmpl2 as wtp

MISC = "misc"
XOLAM_HE = "xolam-he"
QYV = "QyV"

# Use x where plain h would be misleading for the guttural / ḥ slot.


def classify_tmpl(tmpl):
    if not wtp.is_template_with_name(tmpl, 'מ:קו"כ-אם-2'):
        return None
    ketiv_letters = _ketiv_letters(tmpl)
    qere_text = pointed_qere_text(tmpl)
    qere_letters = hl.letters(qere_text)
    ketiv_pointed = _flatten_text(wtp.template_param_val(tmpl, "1"))
    if _is_xolam_he(ketiv_letters, qere_letters, ketiv_pointed, qere_text):
        return XOLAM_HE
    if _is_qyv(ketiv_letters, qere_letters, ketiv_pointed, qere_text):
        return QYV
    return None


def subtype_for_path(tmpl):
    return classify_tmpl(tmpl) or MISC


def pointed_qere_text(tmpl):
    return _flatten_text(wtp.template_param_val(tmpl, "3"))


def _ketiv_letters(tmpl):
    return hl.letters(_flatten_text(wtp.template_param_val(tmpl, "2")))


def _is_xolam_he(ketiv_letters, qere_letters, ketiv_pointed, qere_text):
    if not ketiv_letters.endswith(hl.HE):
        return False
    if qere_letters != ketiv_letters[:-1] + hl.VAV:
        return False
    ketiv_core = _strip_accents_and_punctuation(ketiv_pointed)
    qere_core = _strip_accents_and_punctuation(qere_text)
    return ketiv_core.endswith(hpo.XOLAM + hl.HE) and qere_core.endswith(
        (hl.VAV + hpo.XOLAM, hl.VAV + hpo.XOLAM_XFV)
    )


def _is_qyv(ketiv_letters, qere_letters, ketiv_pointed, qere_text):
    if not ketiv_letters.endswith(hl.VAV):
        return False
    if qere_letters != ketiv_letters[:-1] + hl.YOD + hl.VAV:
        return False
    ketiv_core = _strip_accents_and_punctuation(ketiv_pointed)
    qere_core = _strip_accents_and_punctuation(qere_text)
    return ketiv_core.endswith(hpo.QAMATS + hl.VAV) and qere_core.endswith(
        hpo.QAMATS + hl.YOD + hl.VAV
    )


def _flatten_text(wtel):
    if isinstance(wtel, str):
        return wtel
    if isinstance(wtel, list):
        return "".join(_flatten_text(item) for item in wtel)
    assert wtp.is_template(wtel), wtel
    if wtp.is_template_with_name_in(wtel, tmpln._STD_KQ_TMPL_NAMES):
        return _flatten_text(wtp.template_element(wtel, 2))
    if wtp.is_template_with_name(wtel, "מ:דחי"):
        return _flatten_text(wtp.template_element(wtel, 1))
    if wtp.is_template_with_name(wtel, "מ:קמץ"):
        return _flatten_text(wtp.template_param_val(wtel, "ד"))
    if wtp.is_template_with_name_in(
        wtel, {"מ:לגרמיה-2", "מ:פסק", "מ:מקף אפור", *tmpln._WHITESPACE_TMPL_NAMES}
    ):
        return ""
    return _flatten_text(wtp.template_element(wtel, 1))


_STRIP_PATT = re.compile(
    "["
    + ha.ACCENTS_AND_MTG
    + hpu.MAQ
    + hpu.PASOLEG
    + hpu.SOPA
    + hpu.GERSHAYIM
    + hpu.MCIRC
    + "]"
)


def _strip_accents_and_punctuation(text):
    return _STRIP_PATT.sub("", text)
